mod prof {
    use std::collections::HashMap;
    use std::hash::{Hash, Hasher};
    use std::sync::{Mutex, Once};
    use std::time::Duration;

    #[derive(Default)]
    struct Stat { count: u64, nanos: u128, bytes: u64, dup: u64 }
    #[derive(Default)]
    struct State {
        by_method: HashMap<&'static str, Stat>,
        by_site: HashMap<(&'static str, String), Stat>,
        seen: HashMap<(&'static str, u64), u64>,
        last: Option<&'static str>,
        run: u64,
        runs: HashMap<(&'static str, u64), u64>,
        pairs: HashMap<(&'static str, &'static str), u64>,
    }
    static STATE: Mutex<Option<State>> = Mutex::new(None);
    static INIT: Once = Once::new();
    unsafe extern "C" { fn atexit(cb: extern "C" fn()) -> i32; }

    pub fn enabled() -> bool { std::env::var_os("CALIPER_RPC_PROFILE").is_some() }

    pub fn hash_params(params: &impl serde::Serialize) -> u64 {
        if !enabled() { return 0; }
        let mut h = std::collections::hash_map::DefaultHasher::new();
        serde_json::to_vec(params).unwrap_or_default().hash(&mut h);
        h.finish()
    }

    pub fn record(method: &'static str, at: &std::panic::Location<'static>, hash: u64, took: Duration, bytes: usize) {
        if !enabled() { return; }
        INIT.call_once(|| { unsafe { atexit(dump); } });
        let mut g = STATE.lock().unwrap();
        let st = g.get_or_insert_with(State::default);
        let e = st.by_method.entry(method).or_default();
        e.count += 1; e.nanos += took.as_nanos(); e.bytes += bytes as u64;
        let dup = { let n = st.seen.entry((method, hash)).or_default(); *n += 1; *n > 1 };
        if dup { st.by_method.get_mut(method).unwrap().dup += 1; }
        let site = format!("{}:{}", at.file(), at.line());
        let s = st.by_site.entry((method, site)).or_default();
        s.count += 1; s.nanos += took.as_nanos(); s.bytes += bytes as u64;
        if let Some(prev) = st.last { *st.pairs.entry((prev, method)).or_default() += 1; }
        if st.last == Some(method) { st.run += 1; } else {
            if let Some(prev) = st.last { *st.runs.entry((prev, st.run)).or_default() += 1; }
            st.last = Some(method); st.run = 1;
        }
    }

    extern "C" fn dump() {
        let Ok(mut g) = STATE.lock() else { return };
        let Some(st) = g.take() else { return };
        let total: u64 = st.by_method.values().map(|s| s.count).sum();
        eprintln!("RPCPROF total {total}");
        for (m, s) in &st.by_method {
            eprintln!("RPCPROF method\\t{m}\\t{}\\t{}\\t{}\\t{}", s.count, s.nanos / 1_000_000, s.bytes, s.dup);
        }
        for ((m, site), s) in &st.by_site {
            eprintln!("RPCPROF site\\t{m}\\t{site}\\t{}\\t{}\\t{}", s.count, s.nanos / 1_000_000, s.bytes);
        }
        for ((a, b), n) in &st.pairs { eprintln!("RPCPROF pair\\t{a}\\t{b}\\t{n}"); }
        // run-length: number of runs of length >= 2 per method
        let mut agg: HashMap<&str, (u64, u64)> = HashMap::new();
        for ((m, len), n) in &st.runs { if *len >= 2 { let e = agg.entry(m).or_default(); e.0 += n; e.1 += len * n; } }
        for (m, (runs, items)) in agg { eprintln!("RPCPROF run\\t{m}\\t{runs}\\t{items}"); }
    }
}
