import sys, statistics, collections
def parse(path):
    lines = open(path).read().split('\n')
    idx = max(i for i, l in enumerate(lines) if l == 'RPCPROF BEGIN')
    d = {'method': {}, 'site': {}, 'pair': {}, 'run': {}, 'total': 0}
    for l in lines[idx:]:
        if not l.startswith('RPCPROF'): continue
        p = l.split('\t')
        if p[0].startswith('RPCPROF total'): d['total'] = int(p[0].split()[-1])
        elif p[0] == 'RPCPROF method': d['method'][p[1]] = tuple(map(int, p[2:6]))
        elif p[0] == 'RPCPROF site': d['site'][(p[1], p[2])] = tuple(map(int, p[3:6]))
        elif p[0] == 'RPCPROF pair': d['pair'][(p[1], p[2])] = int(p[3])
        elif p[0] == 'RPCPROF run': d['run'][p[1]] = tuple(map(int, p[2:4]))
    return d
name = sys.argv[1]
runs = [parse(f'/tmp/claude-501/prof/{name}.{i}.err') for i in (1, 2, 3)]
med = lambda xs: statistics.median(xs)
print('==', name, 'total', [r['total'] for r in runs])
ms = set().union(*[r['method'].keys() for r in runs])
rows = []
for m in ms:
    vals = [r['method'].get(m, (0, 0, 0, 0)) for r in runs]
    rows.append((m, med([v[0] for v in vals]), med([v[1] for v in vals]), med([v[2] for v in vals]), med([v[3] for v in vals]), med([r['run'].get(m, (0, 0))[1] for r in runs])))
print('method count ms bytes dup runitems')
for key, label in ((1, 'count'), (2, 'time'), (3, 'bytes')):
    print('-- top by', label)
    for r in sorted(rows, key=lambda r: -r[key])[:10]:
        print('  %-34s %7d %6d %11d dup=%6d inruns=%6d' % r)
print('-- sites (sampled 1/4; counts x4) top by count')
ss = set().union(*[r['site'].keys() for r in runs])
srows = []
for s in ss:
    vals = [r['site'].get(s, (0, 0, 0)) for r in runs]
    srows.append((s[0], s[1], med([v[0] for v in vals]) * 4, med([v[2] for v in vals]) * 4))
for r in sorted(srows, key=lambda r: -r[2])[:int(sys.argv[2]) if len(sys.argv) > 2 else 25]:
    print('  %-30s %6d %10d  %s' % (r[0], r[2], r[3], r[1][:150]))
print('-- top transitions')
ps = set().union(*[r['pair'].keys() for r in runs])
prow = [(p, med([r['pair'].get(p, 0) for r in runs])) for p in ps]
for p, n in sorted(prow, key=lambda x: -x[1])[:12]: print('  %7d %s -> %s' % (n, p[0], p[1]))

